int checkcolumn(int r,int c,int chess1[8][8]){
    int i;
    for(i=0;i<8;i++){
        if(i==r)
        continue;
        else{
            if(chess1[i][c]==1)
            return 1;
        }
    }
    return 0;
}
int checkdiagonal(int r,int c,int chess1[8][8]){
    int i,j;
    j=c+1;
    for(i=r+1;i<8;i++){
        if(j<8){
        if (chess1[i][j]==1)
        return 1;}
        j++;
    }
    j=c-1;
    for(i=r+1;i<8;i++){
        if(j>=0){
        if(chess1[i][j]==1)
        return 1;}
        j--;
    }
    j=c-1;
    for(i=r-1;i>=0;i--){
        if(j>=0){
        if(chess1[i][j]==1)
        return 1;}
        j--;
    }
    j=c+1;
    for(i=r-1;i>=0;i--){
        if(j<8){
        if(chess1[i][j]==1)
        return 1;}
        j++;
    }
    return 0;


}

