#include <stdio.h>
int safe(int mat[8][8],int i,int j){
    int k,l,check=1;
    k=i;
    l=j;
    for(j=0;j<8;++j){
        if(j==l){
                continue;
            }
        else if(mat[i][j]!=0){
                check=0;
                break;
            }
        }
    if(check==1){
        j=l;
        for(i=0;i<8;++i){
            if(i==k){
                continue;
                }
            else if(mat[i][j]!=0){
                check=0;
                break;
                }
            }
        }
    if(check==1){
        i=k;
        j=l;
        if(j>i){
            for((i=0,j=l-k);j<8;(++i,++j)){
                if((i==k)||(j==l)){
                    continue;
                }
                else if(mat[i][j]!=0){
                    check=0;
                    break;
                    }
                }
            }
        else{
            for((j=0,i=k-l);i<8;(++i,++j)){
                if((i==k)||(j==l)){
                    continue;
                }
                else if(mat[i][j]!=0){
                    check=0;
                    break;
                    }
                }
            }
        }
    if(check==1){
        i=k;
        j=l;
        if(i+j<7){
            for((j=0,i=(k+l));i>0;(++j,--i)){
                if((j==l)||(i==k)){
                    continue;
                }
                else if(mat[i][j]!=0){
                    check=0;
                    break;
                }
            }
        }
        else{
            for((i=7,j=(k+l-7));j<8;(++j,--k)){
                if((j==l)||(i==k)){
                    continue;
                }
                else if(mat[i][j]!=0){
                    check=0;
                    break;
                }
            }
        }
    }
    return check;
}


