int issafe(int arr[][8],int a,int b)
{    
    int x=a;
    int y=b;


    for(int i=0;i<8;i++)
    {
      if(i==b)
      continue;

      if(arr[a][i]==1)
      return 0;
    }

    for(int j=0;j<8;j++)
    {
        if(j==a)
        continue;

        if(arr[j][b]==1)
        return 0;
    }

    while((x<8)&&(y<8))
    {
        if(arr[++x][++y]==1)
        return 0;
    }
    x=a;
    y=b;

    while((x>=0)&&(y>=0))
    if(arr[--x][--y]==1)
    return 0;

    x=a;
    y=b;

    while((x<8)&&(y<8)&&(x>=0)&&(y>=0))
    if(arr[--x][++y]==1)
    return 0;

    x=a;
    y=b;

    while((x<8)&&(y<8)&&(x>=0)&&(y>=0))
    if(arr[++x][--y]==1)
    return 0;

    return 1 ;
}

